# Simple login system with email change functionality

# Initialize user data (in real app, this would be stored in a database)
users = {
    "alice@example.com": {
        "password": "password123",
        "email_changed": False
    },
    "bob@example.com": {
        "password": "securepass",
        "email_changed": False
    }
}

def login():
    email = input("Enter your email: ").strip()
    password = input("Enter your password: ").strip()

    if email in users and users[email]["password"] == password:
        print("Login successful!")
        return email
    else:
        print("Invalid email or password.")
        return None

def change_email(current_email):
    if users[current_email]["email_changed"]:
        print("You have already changed your email.")
        return

    old_email = input("Enter your old email: ").strip()
    if old_email != current_email:
        print("Old email does not match.")
        return

    password = input("Confirm your password: ").strip()
    if password != users[current_email]["password"]:
        print("Incorrect password.")
        return

    new_email = input("Enter your new email: ").strip()
    if not new_email or "@" not in new_email or "." not in new_email:
        print("Invalid email format.")
        return

    # Update the email
    users[new_email] = users.pop(current_email)
    users[new_email]["email_changed"] = True
    print(f"Email successfully changed to {new_email}.")

def main():
    print("Welcome to the login system!")

    # Login
    current_email = login()
    if not current_email:
        return

    # Change email if allowed
    change_email(current_email)

if __name__ == "__main__":
    main()

